using ZenithClipper.Editing;
var failed=0;
void Test(string name,Action test){try{test();Console.WriteLine($"PASS {name}");}catch(Exception e){failed++;Console.WriteLine($"FAIL {name}: {e.Message}");}}
void Equal<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}; got {actual}");}
void Reject(Action action){try{action();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}catch(InvalidDataException){return;}throw new Exception("Expected rejection");}
(EditProject p,EditSequence s,EditTrack t,TimelineClip c) Fixture(double speed=1){var c=new TimelineClip{Start=10,SourceIn=20,Duration=100,Speed=speed};var t=new EditTrack{Clips=[c]};var s=new EditSequence{Tracks=[t]};var m=new MediaAsset{DurationSeconds=100};c.MediaId=m.Id;var p=new EditProject{Media=[m],Sequences=[s],ActiveSequenceId=s.Id};return(p,s,t,c);}
Test("fractional frame math",()=>{var r=new FrameRate(30000,1001);Equal(107892L,r.Frames(3600));Equal(1001d,r.Seconds(30000));Reject(()=>new FrameRate(0,1).Frames(1));});
Test("split advances source by speed",()=>{var(p,s,t,c)=Fixture(2);EditCommands.Split(p,s.Id,t.Id,c.Id,40);Equal(30L,c.Duration);Equal(80L,t.Clips[1].SourceIn);Equal(70L,t.Clips[1].Duration);});
Test("reverse split preserves source bounds",()=>{var(p,s,t,c)=Fixture(2);c.Reverse=true;EditCommands.Split(p,s.Id,t.Id,c.Id,40);Equal(160L,c.SourceIn);Equal(20L,t.Clips[1].SourceIn);});
Test("ripple delete moves following clips",()=>{var(p,s,t,c)=Fixture();var next=new TimelineClip{MediaId=c.MediaId,Start=130,Duration=20};t.Clips.Add(next);EditCommands.Delete(p,s.Id,t.Id,c.Id,true);Equal(30L,next.Start);});
Test("locked track rejects edits",()=>{var(p,s,t,c)=Fixture();t.Locked=true;Reject(()=>EditCommands.Split(p,s.Id,t.Id,c.Id,40));Equal(1,t.Clips.Count);});
Test("session snapshots and undo independent",()=>{var(p,s,t,c)=Fixture();var session=new EditorSession(p);p.Name="outside";session.Execute("name",p=>p.Name="changed");var snapshot=session.Project;snapshot.Name="mutated";session.Undo();Equal("Untitled",session.Project.Name);session.Redo();Equal("changed",session.Project.Name);session.MarkSaved();Equal(false,session.Dirty);session.Undo();Equal(true,session.Dirty);});
Test("failed edit atomic",()=>{var(p,s,t,c)=Fixture();var session=new EditorSession(p);Reject(()=>session.Execute("bad",p=>p.Sequences[0].Tracks[0].Clips[0].Start=-1));Equal(10L,session.Project.Sequences[0].Tracks[0].Clips[0].Start);Equal(false,session.CanUndo);});
Test("move trim boundaries",()=>{var(p,s,t,c)=Fixture();Reject(()=>EditCommands.Move(p,s.Id,t.Id,c.Id,t.Id,-1));Reject(()=>EditCommands.Trim(p,s.Id,t.Id,c.Id,0,0));EditCommands.Trim(p,s.Id,t.Id,c.Id,20,50);Equal(30L,c.SourceIn);Equal(50L,c.Duration);});
Test("slip roll rate stretch",()=>{var(p,s,t,c)=Fixture();EditCommands.Slip(p,s.Id,t.Id,c.Id,5);Equal(25L,c.SourceIn);var next=new TimelineClip{MediaId=c.MediaId,Start=110,SourceIn=150,Duration=60};t.Clips.Add(next);EditCommands.Roll(p,s.Id,t.Id,c.Id,next.Id,10);Equal(110L,c.Duration);Equal(120L,next.Start);Equal(160L,next.SourceIn);EditCommands.RateStretch(p,s.Id,t.Id,c.Id,55);Equal(2d,c.Speed);});
Test("store roundtrip autosave corrupt future",()=>{var folder=Path.Combine(Path.GetTempPath(),"zc-tests-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var path=Path.Combine(folder,"project.zcproj");var(p,s,t,c)=Fixture();ProjectStore.Save(path,p);Equal(p.Id,ProjectStore.Load(path).Id);p.Name="recovery";ProjectStore.SaveAutosave(path,p);Equal("recovery",ProjectStore.LoadRecovery(path)!.Name);Equal("Untitled",ProjectStore.Load(path).Name);File.WriteAllText(path,"{bad");Reject(()=>ProjectStore.Load(path));File.WriteAllText(path,"{\"Version\":999}");Reject(()=>ProjectStore.Load(path));Equal(0,Directory.GetFiles(folder,"*.tmp").Length);}finally{Directory.Delete(folder,true);}});
Test("import add track and add clip isolate caller objects",()=>{var(p,s,t,c)=Fixture();var media=new MediaAsset{Kind=MediaKind.Image,Path="missing.png"};var id=EditCommands.Import(p,media);media.Name="outside";Equal("Media",p.Media.Single(m=>m.Id==id).Name);var tid=EditCommands.AddTrack(p,s.Id,TrackKind.Video,"V2");var clip=new TimelineClip{MediaId=id,Duration=100};var cid=EditCommands.AddClip(p,s.Id,tid,clip);clip.Name="outside";Equal("Clip",s.Tracks.Single(x=>x.Id==tid).Clips.Single().Name);Equal(1,ProjectStore.MissingMedia(p).Count(m=>m.Id==id));});
Test("change speed retains source span and link checks locks",()=>{var(p,s,t,c)=Fixture();EditCommands.ChangeSpeed(p,s.Id,t.Id,c.Id,2);Equal(50L,c.Duration);var other=new TimelineClip{MediaId=c.MediaId,Start=100,Duration=20};t.Clips.Add(other);var link=EditCommands.Link(p,s.Id,[c.Id,other.Id]);Equal<Guid?>(link,c.LinkId);Equal<Guid?>(link,other.LinkId);t.Locked=true;Reject(()=>EditCommands.Link(p,s.Id,[c.Id,other.Id]));});
Test("invalid replacement preserves saved bytes",()=>{var folder=Path.Combine(Path.GetTempPath(),"zc-tests-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var path=Path.Combine(folder,"p.zcproj");var(p,s,t,c)=Fixture();ProjectStore.Save(path,p);var original=File.ReadAllText(path);c.Duration=-1;Reject(()=>ProjectStore.Save(path,p));Equal(original,File.ReadAllText(path));}finally{Directory.Delete(folder,true);}});
Test("store refuses overwrite of imported original",()=>{var folder=Path.Combine(Path.GetTempPath(),"zc-tests-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var path=Path.Combine(folder,"source.mp4");File.WriteAllText(path,"original");var(p,s,t,c)=Fixture();p.Media[0].Path=path;Reject(()=>ProjectStore.Save(path,p));Equal("original",File.ReadAllText(path));}finally{Directory.Delete(folder,true);}});
Test("bounded history and arbitrary callbacks respect locks",()=>{var(p,s,t,c)=Fixture();var session=new EditorSession(p);for(var i=1;i<=105;i++){var value=i;session.Execute("rename",p=>p.Name=value.ToString());}for(var i=0;i<100;i++)session.Undo();Equal("5",session.Project.Name);Equal(false,session.CanUndo);session.Execute("lock",p=>p.Sequences[0].Tracks[0].Locked=true);Reject(()=>session.Execute("bypass",p=>p.Sequences[0].Tracks[0].Clips[0].Name="bad"));Equal("Clip",session.Project.Sequences[0].Tracks[0].Clips[0].Name);});
Test("SRT parses BOM CRLF Unicode multiline and mixed decimal separators",()=>{var cues=SubtitleCodec.ParseSrt("\uFEFF7\r\n00:00:01,250 --> 00:00:03.500\r\nZażółć 世界\r\nSecond line\r\n\r\n2\r\n00:00:02.000 --> 00:00:04,000\r\nOverlap\r\n");Equal(2,cues.Count);Equal(1.25,cues[0].StartSeconds);Equal(3.5,cues[0].EndSeconds);Equal("Zażółć 世界\nSecond line",cues[0].Text);Equal("Overlap",cues[1].Text);});
Test("SRT write roundtrips order and multiline text",()=>{SubtitleCue[] original=[new(360001.125,360002.999,"Late\n世界"),new(0,4,"  text with spaces  "),new(2,3,"overlap")];var encoded=SubtitleCodec.WriteSrt(original);Equal(true,encoded.StartsWith("1\n100:00:01,125 --> 100:00:02,999\n"));var cues=SubtitleCodec.ParseSrt(encoded);Equal(3,cues.Count);for(var i=0;i<original.Length;i++)Equal(original[i],cues[i]);Equal(0,SubtitleCodec.ParseSrt("").Count);});
Test("SRT rejects malformed orphan and invalid times",()=>{foreach(var text in new[]{"1\n00:00:03,000 --> 00:00:02,000\nbackwards","1\n-00:00:01,000 --> 00:00:02,000\nnegative","1\n00:60:00,000 --> 01:01:00,000\nbad minutes","1\n00:00:00,000 --> 00:00:02,000\n","1\nnot a time\ntext","1\n00:00:00,000 --> 00:00:02,000\ntext\n\norphan text"})Reject(()=>SubtitleCodec.ParseSrt(text));});
Test("SRT writer rejects nonfinite reversed negative or lossy text",()=>{foreach(var cue in new SubtitleCue[]{new(double.NaN,1,"text"),new(0,double.PositiveInfinity,"text"),new(-1,2,"text"),new(3,2,"text"),new(0,2,"one\n\ntwo"),new(0,2,"")})Reject(()=>SubtitleCodec.WriteSrt([cue]));});
Test("project validation bounds output allocation profiles",()=>{foreach(var size in new[]{(0,1080),(1,1080),(1921,1080),(1920,1081),(16386,1080),(16384,16384)}){var(p,s,t,c)=Fixture();s.Width=size.Item1;s.Height=size.Item2;Reject(()=>ProjectValidation.Validate(p));}var(valid,sequence,_,_)=Fixture();sequence.Width=7680;sequence.Height=4320;ProjectValidation.Validate(valid);});
Test("project validation rejects absurd rational rates",()=>{foreach(var fps in new[]{new FrameRate(0,1),new FrameRate(30,0),new FrameRate(-30,1),new FrameRate(1001,1),new FrameRate(1,11),new FrameRate(1000001,1000000),new FrameRate(30000,1000001)}){var(p,s,t,c)=Fixture();s.Fps=fps;Reject(()=>ProjectValidation.Validate(p));}var(valid,sequence,_,_)=Fixture();sequence.Fps=new FrameRate(30000,1001);ProjectValidation.Validate(valid);valid.Media[0].Kind=MediaKind.Image;sequence.Fps=new FrameRate(1,10);ProjectValidation.Validate(valid);});
Test("project timeline bounds match MLT signed frame limits",()=>{foreach(var range in new[]{((long)int.MaxValue,1L),(0L,(long)int.MaxValue+1),(-1L,1L)}){var(p,s,t,c)=Fixture();p.Media[0].Kind=MediaKind.Image;c.Start=range.Item1;c.Duration=range.Item2;Reject(()=>ProjectValidation.Validate(p));}var(valid,sequence,track,clip)=Fixture();valid.Media[0].Kind=MediaKind.Image;clip.Start=int.MaxValue-1;clip.Duration=1;ProjectValidation.Validate(valid);sequence.Markers.Add(new SequenceMarker{Frame=(long)int.MaxValue+1});Reject(()=>ProjectValidation.Validate(valid));});
Test("project metadata rejects invalid media dimensions and rates",()=>{foreach(var dimensions in new[]{(-1,1080),(1920,-1),(65537,1080)}){var(p,s,t,c)=Fixture();p.Media[0].Width=dimensions.Item1;p.Media[0].Height=dimensions.Item2;Reject(()=>ProjectValidation.Validate(p));}var(valid,_,_,_)=Fixture();valid.Media[0].Fps=new FrameRate(2000,1);Reject(()=>ProjectValidation.Validate(valid));});
Test("loading oversized profile rejects before native use",()=>{var path=Path.Combine(Path.GetTempPath(),"zc-oversized-"+Guid.NewGuid()+".zcproj");try{var(p,s,t,c)=Fixture();s.Width=16384;s.Height=16384;File.WriteAllText(path,System.Text.Json.JsonSerializer.Serialize(p));Reject(()=>ProjectStore.Load(path));}finally{File.Delete(path);}});
Test("locked track permits controls while protecting clip content and kind",()=>{var(p,s,t,c)=Fixture();t.Locked=true;var session=new EditorSession(p);session.Execute("track controls",p=>{var track=p.Sequences[0].Tracks[0];track.Name="Renamed";track.Muted=true;track.Hidden=true;track.GainDb=-6;});var result=session.Project.Sequences[0].Tracks[0];Equal("Renamed",result.Name);Equal(true,result.Muted);Equal(true,result.Hidden);Equal(-6d,result.GainDb);Reject(()=>session.Execute("kind",p=>p.Sequences[0].Tracks[0].Kind=TrackKind.Audio));Reject(()=>session.Execute("remove",p=>p.Sequences[0].Tracks.Clear()));Reject(()=>session.Execute("content",p=>p.Sequences[0].Tracks[0].Clips[0].Start=20));});
Test("native transform limits reject unreasonable output requests",()=>{foreach(var transform in new[]{new ClipTransform{X=101},new ClipTransform{Y=-101},new ClipTransform{ScaleX=101},new ClipTransform{ScaleY=1e308},new ClipTransform{Rotation=360001},new ClipTransform{X=double.NaN}}){var(p,s,t,c)=Fixture();c.Transform=transform;Reject(()=>ProjectValidation.Validate(p));}var(valid,sequence,track,clip)=Fixture();clip.Transform=new ClipTransform{X=100,Y=-100,ScaleX=100,ScaleY=100,Rotation=-360000};ProjectValidation.Validate(valid);});
Test("recovered snapshots remain unsaved until explicitly saved",()=>{var(p,_,_,_)=Fixture();var session=new EditorSession(p);session.MarkUnsaved();Equal(true,session.Dirty);session.MarkSaved();Equal(false,session.Dirty);});
Test("project requires an active sequence",()=>{var(p,_,_,_)=Fixture();p.Sequences.Clear();Reject(()=>ProjectValidation.Validate(p));});
(EditProject p,EditSequence s,EditTrack v,EditTrack a,TimelineClip video,TimelineClip audio) Paired()
{
 var media=new MediaAsset{Kind=MediaKind.Video,HasAudio=true,DurationSeconds=20};var v=new EditTrack{Kind=TrackKind.Video};var a=new EditTrack{Kind=TrackKind.Audio};var s=new EditSequence{Tracks=[v,a]};var p=new EditProject{ActiveSequenceId=s.Id,Sequences=[s],Media=[media]};EditCommands.AppendMedia(p,s.Id,media.Id,30,a.Id);return(p,s,v,a,v.Clips.Single(),a.Clips.Single());
}
Test("append separates source video and audio with explicit intent",()=>{var(p,s,v,a,video,audio)=Paired();Equal(ClipStreamIntent.VideoOnly,video.StreamIntent);Equal(ClipStreamIntent.AudioOnly,audio.StreamIntent);Equal(video.LinkId,audio.LinkId);Equal(video.SourcePairId,audio.SourcePairId);Equal(video.Start,audio.Start);Equal(video.Duration,audio.Duration);ProjectValidation.Validate(p);});
Test("linked move and trim preserve both stream timings",()=>{var(p,s,v,a,video,audio)=Paired();EditCommands.Move(p,s.Id,v.Id,video.Id,v.Id,90);Equal(90L,audio.Start);EditCommands.Trim(p,s.Id,v.Id,video.Id,120,300);Equal(video.Start,audio.Start);Equal(video.SourceIn,audio.SourceIn);Equal(video.Duration,audio.Duration);Equal(30L,audio.SourceIn);});
Test("linked split creates independent left and right link groups",()=>{var(p,s,v,a,video,audio)=Paired();EditCommands.Split(p,s.Id,v.Id,video.Id,150);Equal(2,v.Clips.Count);Equal(2,a.Clips.Count);Equal(v.Clips[0].LinkId,a.Clips[0].LinkId);Equal(v.Clips[1].LinkId,a.Clips[1].LinkId);Equal(false,v.Clips[0].LinkId==v.Clips[1].LinkId);Equal(v.Clips[1].SourceIn,a.Clips[1].SourceIn);EditCommands.Delete(p,s.Id,v.Id,v.Clips[1].Id);Equal(1,v.Clips.Count);Equal(1,a.Clips.Count);});
Test("locked linked partner rejects edits atomically",()=>{var(p,s,v,a,video,audio)=Paired();a.Locked=true;Reject(()=>EditCommands.Move(p,s.Id,v.Id,video.Id,v.Id,100));Reject(()=>EditCommands.Split(p,s.Id,v.Id,video.Id,60));Reject(()=>EditCommands.Delete(p,s.Id,v.Id,video.Id));Equal(30L,video.Start);Equal(1,v.Clips.Count);Equal(1,a.Clips.Count);});
Test("unlink is independent and relink realigns source partner",()=>{var(p,s,v,a,video,audio)=Paired();EditCommands.Unlink(p,s.Id,video.Id);Equal<Guid?>(null,video.LinkId);Equal<Guid?>(null,audio.LinkId);Equal(ClipStreamIntent.VideoOnly,video.StreamIntent);EditCommands.Move(p,s.Id,a.Id,audio.Id,a.Id,120);Equal(30L,video.Start);EditCommands.Relink(p,s.Id,video.Id);Equal(video.Start,audio.Start);Equal(video.LinkId,audio.LinkId);Equal(video.SourceIn,audio.SourceIn);});
Test("linked inspector speed source and duration edits stay synced",()=>{var(p,s,v,a,video,audio)=Paired();EditCommands.ChangeSpeed(p,s.Id,v.Id,video.Id,2);Equal(300L,audio.Duration);Equal(2d,audio.Speed);EditCommands.ChangeLinkedClip(p,s.Id,video.Id,c=>{c.SourceIn=20;c.Duration=200;c.Reverse=true;});Equal(20L,audio.SourceIn);Equal(200L,audio.Duration);Equal(true,audio.Reverse);EditCommands.ChangeLinkedClip(p,s.Id,video.Id,c=>c.Opacity=.5);Equal(1d,audio.Opacity);});
Test("ripple shifts downstream linked partners on other tracks",()=>{var(p,s,v,a,video,audio)=Paired();var v2=new EditTrack{Kind=TrackKind.Video};s.Tracks.Add(v2);EditCommands.AppendMedia(p,s.Id,video.MediaId,900,v2.Id);var next=v2.Clips.Single();var nextAudio=a.Clips.Single(c=>c.LinkId==next.LinkId);EditCommands.Delete(p,s.Id,v.Id,video.Id,true);Equal(300L,next.Start);Equal(300L,nextAudio.Start);});
Test("separated intent and links survive save undo and redo",()=>{var(p,s,v,a,video,audio)=Paired();var session=new EditorSession(p);session.Execute("unlink",x=>EditCommands.Unlink(x,s.Id,video.Id));session.Undo();Equal(video.LinkId,session.Project.Sequences[0].Tracks[0].Clips[0].LinkId);session.Redo();var path=Path.Combine(Path.GetTempPath(),"zc-linked-"+Guid.NewGuid()+".zenith");try{ProjectStore.Save(path,session.Project);var loaded=ProjectStore.Load(path);Equal(ClipStreamIntent.VideoOnly,loaded.Sequences[0].Tracks[0].Clips[0].StreamIntent);Equal<Guid?>(null,loaded.Sequences[0].Tracks[0].Clips[0].LinkId);}finally{File.Delete(path);}});
Test("legacy embedded video can separate and link its source audio",()=>{var(p,s,v,a,video,audio)=Paired();a.Clips.Clear();video.LinkId=null;video.SourcePairId=null;video.StreamIntent=ClipStreamIntent.Auto;EditCommands.Relink(p,s.Id,video.Id);Equal(1,a.Clips.Count);Equal(ClipStreamIntent.VideoOnly,video.StreamIntent);Equal(video.LinkId,a.Clips.Single().LinkId);});
return failed==0?0:1;






